style.css:
@-moz-document domain("youtube.com") {
/* ═══════════════════════════════════════════════
   ? STRAWBERRY SHORTCAKE × SANRIO YOUTUBE ?
   soft strawberry milk / cream / raspberry
   ═══════════════════════════════════════════════ */

:root {
    --strawberry: #e94b7b;
    --raspberry: #d92f69;
    --hotpink: #f36f9f;
    --baby-pink: #ffd5e2;
    --pale-pink: #fff0f4;
    --milk: #fff9f5;
    --cream: #fff4e9;
    --gingham: #f7b7c8;
    --brown: #7a4b55;
    --soft-brown: #9b6873;
}

/* ═════ MAIN BACKGROUND ═════ */

html,
body,
ytd-app,
#content,
#page-manager {
    background-color: var(--pale-pink) !important;
    color: var(--brown) !important;
}

/* subtle strawberry-shortcake grid */
ytd-app {
    background-image:
        linear-gradient(
            rgba(255,255,255,.38) 1px,
            transparent 1px
        ),
        linear-gradient(
            90deg,
            rgba(255,255,255,.38) 1px,
            transparent 1px
        ) !important;

    background-size: 34px 34px !important;
}


/* ═════ TOP HEADER ═════ */

#masthead-container,
ytd-masthead,
#masthead {
    background: linear-gradient(
        90deg,
        #f8a9c0,
        #f58caf,
        #f7aec4
    ) !important;

    border-bottom: 2px solid #e94b7b !important;
    box-shadow: 0 3px 14px rgba(217,47,105,.15) !important;
}


/* ═════ SEARCH BAR ═════ */

#search-form,
ytd-searchbox,
#container.ytd-searchbox {
    background: var(--milk) !important;
    border-color: #ef8dac !important;
}

ytd-searchbox #container {
    border: 2px solid #ef8dac !important;
    border-radius: 25px 0 0 25px !important;
    background: var(--milk) !important;
}

ytd-searchbox input {
    color: var(--brown) !important;
}

ytd-searchbox input::placeholder {
    color: #b97c8c !important;
}


/* ═════ SEARCH BUTTON ═════ */

#search-icon-legacy {
    background: #ffc6d7 !important;
    border: 2px solid #ef8dac !important;
    border-radius: 0 25px 25px 0 !important;
}

#search-icon-legacy:hover {
    background: #f69aba !important;
}


/* ═════ LEFT SIDEBAR ═════ */

#guide-content,
ytd-guide-renderer,
ytd-mini-guide-renderer {
    background: #fff6f8 !important;
}

ytd-guide-entry-renderer,
ytd-mini-guide-entry-renderer {
    border-radius: 14px !important;
    margin: 3px 7px !important;
}

ytd-guide-entry-renderer:hover,
ytd-mini-guide-entry-renderer:hover {
    background: #ffd6e2 !important;
}

ytd-guide-entry-renderer[active] {
    background: #f9bfd0 !important;
}


/* ═════ CATEGORY CHIPS ═════ */

yt-chip-cloud-chip-renderer,
yt-chip-cloud-chip-renderer yt-formatted-string,
yt-chip-cloud-chip-renderer #chip-container {
    border-radius: 20px !important;
}

yt-chip-cloud-chip-renderer #chip-container {
    background: #ffe0e9 !important;
    color: var(--brown) !important;
    border: 1px solid #f5b0c5 !important;
}

yt-chip-cloud-chip-renderer[selected] #chip-container {
    background: var(--raspberry) !important;
    color: white !important;
}


/* ═════ VIDEO CARDS ═════ */

ytd-rich-item-renderer,
ytd-video-renderer {
    border-radius: 18px !important;
}

ytd-rich-item-renderer:hover {
    background: rgba(255,214,226,.45) !important;
}


/* thumbnails */

ytd-thumbnail img {
    border-radius: 16px !important;
}

ytd-thumbnail {
    border-radius: 16px !important;
    overflow: hidden !important;
}

ytd-rich-item-renderer:hover ytd-thumbnail {
    box-shadow:
        0 0 0 2px #f3a2ba,
        0 7px 18px rgba(222,72,116,.17) !important;
}


/* ═════ VIDEO TEXT ═════ */

#video-title,
#video-title-link {
    color: #67434b !important;
}

#metadata-line,
#metadata,
ytd-video-meta-block {
    color: #a06d79 !important;
}


/* ═════ BUTTONS ═════ */

button,
yt-button-shape button {
    border-radius: 20px !important;
}

yt-button-shape button:hover {
    background: #ffd2df !important;
}


/* ═════ CREATE BUTTON ═════ */

ytd-button-renderer button,
yt-button-shape[shape="button"] button {
    background: #f7b2c7 !important;
    color: #6d3e49 !important;
}


/* ═════ SHORTS ═════ */

ytd-rich-section-renderer {
    background: transparent !important;
}

ytd-rich-section-renderer #title {
    color: var(--raspberry) !important;
}


/* ═════ SCROLLBAR ═════ */

::-webkit-scrollbar {
    width: 12px !important;
}

::-webkit-scrollbar-track {
    background: #fff0f4 !important;
}

::-webkit-scrollbar-thumb {
    background: #f29ab5 !important;
    border: 3px solid #fff0f4 !important;
    border-radius: 20px !important;
}

::-webkit-scrollbar-thumb:hover {
    background: #e66d94 !important;
}


/* ═════ MENUS / POPUPS ═════ */

ytd-popup-container tp-yt-paper-listbox,
ytd-menu-popup-renderer,
tp-yt-paper-dialog {
    background: #fff7f8 !important;
    border: 2px solid #f4b2c5 !important;
    border-radius: 18px !important;
    box-shadow: 0 10px 35px rgba(160,60,90,.18) !important;
}


/* ═════ TOOLTIP ═════ */

tp-yt-paper-tooltip .yt-paper-tooltip {
    background: #d94b76 !important;
    color: white !important;
    border-radius: 9px !important;
}


/* ═════ LINKS ═════ */

a:hover,
#video-title:hover {
    color: #d92f69 !important;
}


/* ═══════════════════════════════════════
   ? LITTLE STRAWBERRY DETAILS
   ═══════════════════════════════════════ */

ytd-rich-section-renderer #title::before {
    content: "? ";
}

ytd-rich-section-renderer #title::after {
    content: " ♡";
}

#logo::before {
    content: "?";
    font-size: 18px;
    margin-right: 4px;
}

#guide-section-title::after {
    content: " ♡";
    color: #e94b7b;
}


/* ═════ SELECTION ═════ */

::selection {
    background: #f59bb7 !important;
    color: white !important;
}


/* ═════ FOCUS ═════ */

input:focus,
button:focus {
    outline-color: #ed7da0 !important;
}


/* ═════ WATCH PAGE ═════ */

ytd-watch-flexy,
#columns,
#primary,
#secondary {
    background: var(--pale-pink) !important;
}


/* comments */

ytd-comments,
ytd-comment-thread-renderer {
    color: var(--brown) !important;
}


/* description box */

#description.ytd-watch-metadata {
    background: #ffe4ec !important;
    border: 1px solid #f7b5c8 !important;
    border-radius: 18px !important;
}


/* ═════ PROFILE / ACCOUNT MENU ═════ */

ytd-multi-page-menu-renderer,
ytd-active-account-header-renderer {
    background: #fff5f7 !important;
}

ytd-compact-link-renderer:hover {
    background: #ffd8e3 !important;
}


/* ═════ FINAL SOFTENING ═════ */

* {
    scrollbar-color: #f29ab5 #fff0f4;
}
}
